def find(a, x):
    lo, hi = 0, len(a) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] == x:
            return mid
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

char *copy(const char *s) {
    char *p = malloc(strlen(s));
    strcpy(p, s);
    return p;
}

def f(n):
    total = 0
    i = n
    while i > 1:
        for j in range(i):
            total += 1
        i //= 2
    return total
